function captureSetInput(el){const row=el.closest('.set-row');if(!row||el.type!=='number')return false;const entry=state.draft?.exercises.find(x=>x.id===row.dataset.id),set=entry?.sets[+row.dataset.set];if(!set)return false;const result=C.parseSetField(el.dataset.field,el.value),values=el.dataset.side?set.sideRecords?.[el.dataset.side]:set;if(!values)return false;el.setAttribute('aria-invalid',String(!result.valid));if(!result.valid){if(set.done){set.done=false;save();}return true;}values[el.dataset.field]=result.value;if(set.done&&!C.validSet(set))set.done=false;save();return true;}
document.addEventListener('change',async e=>{const el=e.target,row=el.closest('.set-row');if(row){const entry=state.draft?.exercises.find(x=>x.id===row.dataset.id),set=entry?.sets[+row.dataset.set];if(!set)return;if(el.dataset.field==='done'){if(el.checked&&set.recording&&!set.recording.legacy&&!set.recording.loadConvention){el.checked=false;return toast('先选择本机重量的记法。');}if(el.checked&&(!C.validSet(set)||[...row.querySelectorAll('input[type=number]')].some(i=>i.value===''||!C.parseSetField(i.dataset.field,i.value).valid))){el.checked=false;return toast('先填重量、次数与余力；双侧动作两边完成后再勾选。');}set.done=el.checked;if(entry.shoulder){if(el.checked)set.doneAt=Date.now();else delete set.doneAt;}save();render();return;}captureSetInput(el);return;}
if(el.dataset.check!=null){if(state.draft)state.draft.checks[+el.dataset.check]=el.checked;save();return;}
if(el.dataset.change==='equipment-unit'){const entry=state.draft?.exercises.find(e=>e.id===el.dataset.id),v=entry&&E.current(entry);if(!v||!v.conventions.includes(el.value))return;if(entry.sets.some(t=>t.done||setHasInput(t))&&!await confirmAction('改记重方式后，已完成组保留原单位；未完成组清空，避免把每臂与合计重量混用。继续？')){el.value=entry.equipment.convention;return;}E.select(entry,v.id,el.value,structuredClone(entry.equipment.setup));save();render();return;}
if(el.dataset.change==='variant'){const entry=state.draft?.exercises.find(x=>x.id===el.dataset.id);if(entry&&entry.variant!==el.value){if(entry.sets.some(t=>t.done||t.kg!=null||t.reps!=null)&&!await confirmAction('更换器械会清空本动作已填的组数据，避免混用不同器械重量。继续？')){el.value=entry.variant;return;}entry.variant=el.value;const ex=byId(entry.id),n=entry.extra?1:entry.id==='latrow'&&el.value==='直臂绳索下压'?2:ex.sets;entry.sets=Array.from({length:n},()=>({kg:null,reps:null,rir:2,done:false,quality:true}));save();render();}return;}
if(el.dataset.blendIngredient){const q=plan(),id=el.dataset.blendIngredient;if(q.eaten.includes('blend')){el.checked=!el.checked;return toast('先取消已喝，再调整食材。');}const ingredient=D.blendIngredients.find(i=>i.id===id);if(!ingredient||ingredient.group==='core')return;q.blendRecipe=q.blendRecipe||B.defaultRecipe(D.blendIngredients);q.blendRecipe.included=q.blendRecipe.included.filter(x=>x!==id);if(el.checked)q.blendRecipe.included.push(id);delete q.blendSnapshot;save();renderRecipeKeepScroll(id);return;}
if(el.dataset.eaten){const q=plan();q.eaten=q.eaten.filter(x=>x!==el.dataset.eaten);if(el.checked){q.eaten.push(el.dataset.eaten);if(el.dataset.eaten==='blend')q.blendSnapshot=B.capture(D.blendIngredients,q);}else if(el.dataset.eaten==='blend')delete q.blendSnapshot;save();render();return;}
if(el.dataset.side!=null){plan().sides[+el.dataset.side]=el.value;save();render();return;}
if(el.dataset.change==='blend-amount'){if(plan().eaten.includes('blend'))return toast('先取消已喝，再修改份量。');plan().blendAmount=Number(el.value);save();render();return;}
if(el.dataset.change==='blend-days'){state.blendDays=Number(el.value);save();render();return;}
if(el.id==='waist-concern'){state.waistConcern=el.checked;save();render();return;}
if(el.id==='recovery'&&state.draft){state.draft.recovery=el.value;save();return;}
if(el.id==='session-note'&&state.draft){state.draft.note=el.value;save();}
});
document.addEventListener('input',e=>{if(captureSetInput(e.target))return;if(e.target.id==='session-note'&&state.draft){state.draft.note=e.target.value;save();return;}if(['doc-search','library-search'].includes(e.target.id)){const id=e.target.id,pos=e.target.selectionStart;if(id==='doc-search')docSearch=e.target.value;else librarySearch=e.target.value;const scroll=$('#main').scrollTop;render();$('#'+id).focus({preventScroll:true});$('#'+id).setSelectionRange(pos,pos);$('#main').scrollTop=scroll;}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>50000000){e.target.value='';return toast('备份超过50MB，未导入。');}try{const parsed=JSON.parse(await file.text()),data=parsed.data;if(parsed.app!=='BulkPlan'||!C.validateState(data))throw Error();if(await confirmAction(`恢复此备份将替换当前本机数据：${data.sessions.length}次训练、${data.weights.length}天体重。建议先导出当前记录。是否继续？`)){state=data;B.preserveConsumedLegacy(state);invalidRaw=null;selectedDay=state.draft?.day||C.CYCLE[state.cursor];save();render();toast('备份已恢复。');}}catch{toast('文件不是有效的BulkPlan备份，未更改本机数据。');}e.target.value='';});
